function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function call(path,options={}){const response=await fetch(origin()+path,{headers:{Accept:'application/json','Content-Type':'application/json'},...options});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
async function run(input){const action=String(input.action||''),id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const base='/api/validation/projects/'+encodeURIComponent(id);if(action==='get')return call(base);if(action==='validate_source'){if(!input.source)throw new Error('validation.py source is required');return call('/api/validation/validate',{method:'POST',body:JSON.stringify({source:input.source})})}const current=await call(base);if(input.confirm_write!==true)throw new Error('Editing validation.py requires confirm_write=true');if(action==='replace_source'){if(!input.source)throw new Error('complete validation.py source is required');return call(base,{method:'PUT',body:JSON.stringify({source:input.source,expected_source_sha256:current.source_sha256,confirm_write:true})})}if(action==='update_parameters'){if(!Array.isArray(input.edits)||!input.edits.length)throw new Error('edits are required');return call(base+'/parameters',{method:'POST',body:JSON.stringify({edits:input.edits,expected_source_sha256:current.source_sha256,confirm_write:true})})}throw new Error('unsupported validation source action')}
